174	    }
175	    else if (whence == SEEK_CUR)
176	    {
177	        new_pos = file_offset_of_buffer_end - (working_buffer.end() - pos) + offset;
178	    }
179	    else
180	    {
181	        throw Exception("ReadBufferFromFileDescriptor::seek expects SEEK_SET or SEEK_CUR as whence", ErrorCodes::ARGUMENT_OUT_OF_BOUND);
182	    }
183	
184	    /// Position is unchanged.
185	    if (new_pos + (working_buffer.end() - pos) == file_offset_of_buffer_end)
186	        return new_pos;
187	
188	    while (true)
189	    {
190	        if (file_offset_of_buffer_end - working_buffer.size() <= new_pos && new_pos <= file_offset_of_buffer_end)
191	        {
192	            /// Position is still inside the buffer.
193	            /// Probably it is at the end of the buffer - then we will load data on the following 'next' call.
194	
195	            pos = working_buffer.end() - file_offset_of_buffer_end + new_pos;
