211	    assert(!prefetch_future.valid());
212	
213	    /// Position is out of the buffer, we need to do real seek.
214	    off_t seek_pos = required_alignment > 1
215	        ? new_pos / required_alignment * required_alignment
216	        : new_pos;
217	
218	    /// First reset the buffer so the next read will fetch new data to the buffer.
219	    resetWorkingBuffer();
220	
221	    /// Just update the info about the next position in file.
